WITH latest AS (SELECT *, RANK() OVER (PARTITION BY region ORDER BY opened_date DESC) AS dedup_rank FROM stores QUALIFY dedup_rank = 1) SELECT CASE WHEN sqft >= 14831 THEN 'LARGE' ELSE 'SMALL' END AS sqft_tier, COUNT(DISTINCT id) AS distinct_ids, AVG(sqft) FILTER (WHERE city = 'Singapore') AS singapore_avg_sqft, AVG(sqft) FILTER (WHERE region = 'North') AS north_avg_sqft, ROUND(AVG(sqft), 2) AS avg_sqft, BIT_AND(sqft) AS sqft_bit_and FROM latest GROUP BY 1 ORDER BY avg_sqft DESC NULLS LAST;
